import net.civeira.phylax.features.oauth.rbac.domain.RoleGrant;
import net.civeira.phylax.features.oauth.rbac.domain.ScopeList;

/**
 * Domain port for storing RBAC metadata.
 *
 * Responsibilities: - Register scopes and resource schemas for clients. - Return granted roles for
 * a relying party.
 *
 * Design notes: - Implemented by infrastructure storage adapters. - Used by RBAC registration
 * endpoints.
 */
public interface RbacStoreGateway {
  /**
   * Registers scopes for a relying party.
   *
   * Stores resource scopes to support authorization checks. Implementations should validate payload
   * structure.
   *
   * @param relayParty relying party identifier
   * @param paramMap list of scope lists
   */
  void registerScopes(String relayParty, List<ScopeList> paramMap);

  /**
   * Registers resource schemas for a relying party.
   *
   * Stores property lists to support fine-grained access. Implementations should validate payload
   * structure.
   *
   * @param relayParty relying party identifier
   * @param paramMap list of property lists
   */
  void registerSchema(String relayParty, List<PropertyList> paramMap);

  /**
   * Returns role grants for a relying party.
   *
   * Used to expose granted roles and scopes to clients. Returns an empty list when no grants exist.
   *
   * @param relayParty relying party identifier
   * @return list of role grants
   */
  List<RoleGrant> granted(String relayParty);
}
